def refresh_prices(hf_root: Path, members: list[UniverseMember]) -> str:
    revision = HfApi().dataset_info(REPO_ID).sha
    if not revision:
        raise RuntimeError('missing HF revision')
    files = [f"data/daily/{ALIASES.get(member.symbol, member.symbol)}.parquet" for member in members]
    files.extend(["README.md", "data/state/ingestion_state.parquet"])
    snapshot_download(REPO_ID, repo_type="dataset", revision=revision, allow_patterns=files, local_dir=hf_root)
    return str(revision)

def yahoo_symbol(member: UniverseMember) -> str:
    if member.kind == "etf" and member.price_symbol:
        return member.price_symbol.replace(".DEX", ".DE").replace(".LON", ".L").replace(".SWX", ".SW")
    symbol = member.symbol.strip()
    if member.mic in {"XCSE", "XSTO", "XHEL"}:
        symbol = symbol.replace(" ", "-")
    if member.mic == "XLON":
        symbol = symbol.rstrip(".").replace(".", "-")
    return symbol + YAHOO_SUFFIX.get(member.mic, "")

def _store_yahoo_frame(root: Path, provider_symbol: str, frame: object) -> bool:
    try:
        prices = frame[["Adj Close"]].dropna().reset_index()  # type: ignore[index]
        prices.columns = ["date", "adjusted_close"]
        prices["date"] = prices["date"].dt.strftime("%Y-%m-%d")
        if prices.empty:
            return False
        path = _csv_path(root, provider_symbol)
        _atomic_write_text(path, prices.to_csv(index=False))
        return True
    except Exception:
        return False

def refresh_global_prices(root: Path, members: list[UniverseMember]) -> dict[str, str]:
    root.mkdir(parents=True, exist_ok=True)
    provider_symbols = sorted({yahoo_symbol(member) for member in members})
    errors: dict[str, str] = {}
    # Fetch the complete adjusted series: a recent append cannot rebase old anchors.
    for start in range(0, len(provider_symbols), 50):
        batch = provider_symbols[start : start + 50]
        try:
            data = yf.download(
                batch, period="max", auto_adjust=False, actions=False,
                group_by="ticker", progress=False, threads=True, timeout=30,
            )
        except Exception as error:
            errors.update({symbol: str(error) for symbol in batch})
            continue
        for symbol in batch:
            try:
                frame = data[symbol] if len(batch) > 1 else data
                if not _store_yahoo_frame(root, symbol, frame):
                    errors[symbol] = 'empty or invalid adjusted-price refresh'
            except Exception as error:
                errors[symbol] = str(error)
    return errors

def compute_current_signals(
    members: list[UniverseMember],
    monthly: dict[str, list[tuple[date, float]]],
    latest: dict[str, tuple[date, float]],
    *,
    key_by_identity: bool = False,
    source_url: str = SOURCE_URL,
    as_of: date | None = None,
) -> list[dict[str, object]]:
    as_of = as_of or datetime.now(timezone.utc).date()
    results: list[dict[str, object]] = []
    for member in members:
        symbol = member.symbol
        lookup_key = member.stable_identity if key_by_identity else symbol
        rows = [(day, price) for day, price in monthly.get(lookup_key, []) if day <= as_of]
        if not rows or lookup_key not in latest:
            continue
        series = {month_key(day): (day, price) for day, price in rows}
        latest_day, latest_price = latest[lookup_key]
        if latest_day > as_of or latest_day.year != as_of.year:
            continue
        current_month = month_key(latest_day)
        closed_months = sorted(key for key in series if key < current_month)
        episodes: list[dict[str, object]] = []
        for run_year in range(2005, latest_day.year + 1):
            anchors = [(year, 12) for year in range(run_year - 5, run_year)]
            if any(anchor not in series for anchor in anchors):
                continue
            prices = [series[anchor][1] for anchor in anchors]
            mean = sum(prices) / 5
            slope = sum((x - 2) * (price - mean) for x, price in enumerate(prices)) / 10
            intercept = mean - 2 * slope
            if slope <= 0 or intercept + 4 * slope <= 0:
                continue
            run_month: tuple[int, int] | None = None
            for key in closed_months:
                if key[0] < run_year:
                    continue
                trend = trend_value(intercept, slope, run_year, key)
                if trend <= 0:
                    continue
                if run_month is None:
                    if key[0] > run_year:
                        break
                    if series[key][1] >= 1.30 * trend:
                        run_month = key
                elif key > run_month and series[key][1] <= 1.10 * trend:
                    episodes.append(
                        {
                            "run_year": run_year,
                            "run_month": f"{run_month[0]:04d}-{run_month[1]:02d}",
                            "first_entry_month": f"{key[0]:04d}-{key[1]:02d}",
                            "anchors": [
                                {"month": f"{anchor[0]:04d}-12", "adjusted_close": round(price, 8)}
                                for anchor, price in zip(anchors, prices)
                            ],
                            "trend_slope": round(slope, 8),
                            "entry_close": round(series[key][1], 8),
                            "entry_trend": round(trend, 8),
                            "entry_ratio": round(series[key][1] / trend, 8),
                            "_slope": slope,
                            "_intercept": intercept,
                        }
                    )
                    break
        if not episodes:
            continue
        episode = max(episodes, key=lambda item: str(item["first_entry_month"]))
        current_trend = trend_value(
            float(episode.pop("_intercept")),
            float(episode.pop("_slope")),
            int(episode["run_year"]),
            current_month,
        )
        current_ratio = latest_price / current_trend if current_trend > 0 else 999.0
        if str(episode["first_entry_month"])[:4] != str(as_of.year) or current_ratio > 1.10:
            continue
        results.append(
            {
                "stable_identity": member.stable_identity,
                "symbol": member.symbol,
                "name": member.name,
                "kind": member.kind,
                "region": member.region,
                "mic": member.mic,
                **episode,
                "latest_date": latest_day.isoformat(),
                "latest_close": round(latest_price, 8),
                "current_trend": round(current_trend, 8),
                "current_ratio": round(current_ratio, 8),
                "source": source_url,
                "override_status": "BLACK_SWAN_REVIEW_PENDING",
            }
        )
    return sorted(results, key=lambda row: (str(row["first_entry_month"]), -float(row["current_ratio"]), str(row["stable_identity"])), reverse=True)

def _cohort_index(stable_identity: str, policy_version: str, cohort_count: int) -> int:
    digest = hashlib.sha256(f"{policy_version}|{stable_identity}".encode("utf-8")).digest()
    return int.from_bytes(digest[:8], "big") % cohort_count

def assign_cohorts(
    members: Iterable[UniverseMember], *, policy_version: str = "screen-v1", cohort_count: int = 6
) -> dict[int, list[UniverseMember]]:
    cohorts = {index: [] for index in range(cohort_count)}
    for member in members:
        cohorts[_cohort_index(member.stable_identity, policy_version, cohort_count)].append(member)
    for values in cohorts.values():
        values.sort(key=lambda item: item.stable_identity)
    return cohorts

def _xlsx_rows(path: Path) -> list[dict[str, str]]:
    namespace = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}
    tag = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"
    with ZipFile(path) as archive:
        strings_root = ET.fromstring(archive.read("xl/sharedStrings.xml"))
        shared = ["".join(text.text or "" for text in item.iter(tag)) for item in strings_root]
        sheet = ET.fromstring(archive.read("xl/worksheets/sheet1.xml"))
    rows: list[dict[str, str]] = []
    for row in sheet.findall(".//m:row", namespace):
        values: dict[str, str] = {}
        for cell in row.findall("m:c", namespace):
            ref = str(cell.get("r", ""))
            match = re.match(r"[A-Z]+", ref)
            value_node = cell.find("m:v", namespace)
            value = "" if value_node is None or value_node.text is None else value_node.text
            if cell.get("t") == "s" and value:
                value = shared[int(value)]
            if match is not None:
                values[match.group()] = value.strip()
        rows.append(values)
    return rows

def _is_spy_equity_candidate(row: dict[str, str]) -> bool:
    ticker = row.get("B", "").strip()
    identifier = row.get("C", "").strip().upper()
    currency = row.get("H", "").strip()
    return bool(
        ticker
        and ticker not in {"Ticker", "-"}
        and currency == "USD"
        and "CVR" not in identifier
    )

def load_universe_sources(root: Path | str, etf_registry: Path | str) -> list[UniverseMember]:
    fixture_root = Path(root)
    combined: dict[str, UniverseMember] = {}
    for partition in (_load_us(fixture_root), _load_europe(fixture_root), _load_etfs(Path(etf_registry))):
        overlap = set(combined).intersection(partition)
        if overlap:
            raise ValueError(f"identity collision across asset partitions: {sorted(overlap)}")
        combined.update(partition)
    cohorts = assign_cohorts(combined.values(), policy_version="screen-v1", cohort_count=6)
    for index, members in cohorts.items():
        if len(members) > 216:
            raise ValueError(f"cohort {index} exceeds freshness capacity")
        if not {"US", "EU"}.issubset({member.region for member in members}) or not any(member.kind == "etf" for member in members):
            raise ValueError(f"cohort {index} lacks mixed-region/ETF coverage")
    return sorted(combined.values(), key=lambda member: member.stable_identity)

def resolve_ledger_path(explicit: str | None = None) -> Path:
    if explicit:
        return Path(explicit).expanduser()
    env = os.environ.get("RADAR_CITATION_LEDGER", "").strip()
    if env:
        return Path(env).expanduser()
    return Path("state/citations/ledger.json")

def load_ledger(path: Path) -> dict[str, Any]:
    if not path.exists():
        return {"version": SCHEMA_VERSION, "sources": []}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError) as exc:
        raise SystemExit(f"error: ledger at {path} is unreadable ({exc}); run `reset` to start over")
    if not isinstance(data, dict) or not isinstance(data.get("sources"), list):
        raise SystemExit(f"error: ledger at {path} has an unexpected shape; run `reset`")
    return data

class _LedgerLock:
    """Best-effort cross-process lock (O_EXCL lockfile, stdlib only).

    Parallel subagents can share one ledger via --ledger; without a lock two
    concurrent ``add`` calls can assign the same id.  Falls through after the
    timeout rather than blocking a task forever — a stale lock must never
    wedge the ledger.
    """

    def __init__(self, path: Path, timeout: float = 5.0) -> None:
        self.lock_path = path.with_suffix(path.suffix + ".lock")
        self.timeout = timeout
        self.fd: int | None = None

    def __enter__(self) -> _LedgerLock:
        self.lock_path.parent.mkdir(parents=True, exist_ok=True)
        deadline = time.monotonic() + self.timeout
        while True:
            try:
                self.fd = os.open(str(self.lock_path), os.O_CREAT | os.O_EXCL | os.O_WRONLY)
                return self
            except FileExistsError:
                if time.monotonic() >= deadline:
                    # Assume a stale lock from a crashed run.
                    try:
                        self.lock_path.unlink()
                    except OSError:
                        return self
                    continue
                time.sleep(0.05)

    def __exit__(self, *_exc: object) -> None:
        if self.fd is not None:
            try:
                os.close(self.fd)
            except OSError:
                pass
        try:
            self.lock_path.unlink()
        except OSError:
            pass

def __enter__(self) -> _LedgerLock:
    self.lock_path.parent.mkdir(parents=True, exist_ok=True)
    deadline = time.monotonic() + self.timeout
    while True:
        try:
            self.fd = os.open(str(self.lock_path), os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            return self
        except FileExistsError:
            if time.monotonic() >= deadline:
                # Assume a stale lock from a crashed run.
                try:
                    self.lock_path.unlink()
                except OSError:
                    return self
                continue
            time.sleep(0.05)

def __exit__(self, *_exc: object) -> None:
    if self.fd is not None:
        try:
            os.close(self.fd)
        except OSError:
            pass
    try:
        self.lock_path.unlink()
    except OSError:
        pass

def urls_from_json(payload: Any) -> list[tuple[str, str]]:
    """Walk arbitrary JSON tool output collecting (url, title) pairs.

    Handles web_search (``data.web[]``), web_extract (``results[]``) and any
    other nesting, in document order, deduped.
    """
    found: list[tuple[str, str]] = []
    seen: set[str] = set()

    def walk(node: Any) -> None:
        if isinstance(node, dict):
            url = node.get("url") or node.get("link") or node.get("source_url")
            if isinstance(url, str) and url.startswith(("http://", "https://")):
                key = normalize_url(url)
                if key not in seen:
                    seen.add(key)
                    raw_title = node.get("title") or node.get("name") or ""
                    found.append((url, raw_title if isinstance(raw_title, str) else ""))
            for value in node.values():
                walk(value)
        elif isinstance(node, list):
            for item in node:
                walk(item)

    walk(payload)
    return found

def walk(node: Any) -> None:
