def validate_investment_frame(value: object) -> None:
    """Validate a supplied forecast frame; old unknown frames remain unknown."""
    if value is None:
        return
    if not isinstance(value, Mapping):
        raise ContractError("investment_frame must be an object")
    try:
        start = date.fromisoformat(str(value["horizon_start_date"]))
        end = date.fromisoformat(str(value["horizon_end_date"]))
    except (KeyError, ValueError) as error:
        raise ContractError("investment_frame requires ISO start/end dates") from error
    if start.isoformat() != value["horizon_start_date"] or end.isoformat() != value["horizon_end_date"]:
        raise ContractError("investment_frame dates must be canonical YYYY-MM-DD")
    if end <= start or (end.year, end.month, end.day) > (start.year + 5, start.month, start.day):
        raise ContractError("investment_frame needs a future endpoint within five years of its original start")
    if value.get("comparison_currency") != "EUR" or not isinstance(value.get("report_path"), str) or not value["report_path"].strip():
        raise ContractError("investment_frame requires EUR comparison and a full report path")

def validate_review(kind: str, payload: Mapping[str, object]) -> None:
    validate_investment_frame(payload.get("investment_frame"))
    missing_common = sorted(field for field in COMMON_FIELDS if not payload.get(field))
    if missing_common:
        raise ContractError("review missing common fields: " + ", ".join(missing_common))
    try:
        date.fromisoformat(str(payload["evidence_as_of"]))
    except ValueError as exc:
        raise ContractError("evidence_as_of must be an ISO date") from exc
    specific = STOCK_FIELDS if kind == "stock" else ETF_FIELDS
    missing_specific = sorted(field for field in specific if not payload.get(field))
    if missing_specific:
        label = "stock" if kind == "stock" else "ETF"
        raise ContractError(f"{label} review missing fields: " + ", ".join(missing_specific))
    if kind == "stock":
        customer_economics = payload["customer_economics"]
        if not isinstance(customer_economics, Mapping):
            raise ContractError("stock review customer_economics must be a mapping")
        missing_customer_economics = sorted(
            field
            for field in CUSTOMER_ECONOMICS_FIELDS
            if not isinstance(customer_economics.get(field), str)
            or not str(customer_economics[field]).strip()
        )
        if missing_customer_economics:
            raise ContractError(
                "stock review customer_economics missing fields: "
                + ", ".join(missing_customer_economics)
            )

def monthly_brief_context(radar: Any, period: str) -> dict[str, Any]:
    """Bind the current month's actual episodes, baselines, reviews and reports."""
    if not radar.monthly_position_review_status(period)["complete"]:
        raise ContractError("monthly position review is incomplete")
    positions = []
    with radar.connect() as connection:
        for row in connection.execute("SELECT * FROM positions WHERE status='ACTIVE' ORDER BY id").fetchall():
            position = dict(row)
            baseline = connection.execute(
                "SELECT * FROM position_baselines WHERE position_id=? ORDER BY version DESC LIMIT 1",
                (position["id"],),
            ).fetchone()
            review = connection.execute(
                """SELECT pr.* FROM position_reviews pr
                   WHERE position_id=? AND substr(review_date,1,7)=?
                     AND NOT EXISTS (SELECT 1 FROM position_reviews child WHERE child.supersedes_review_id=pr.id)""",
                (position["id"], period),
            ).fetchone()
            if baseline is None or review is None:
                raise ContractError("monthly brief needs a baseline and review for every active episode")
            baseline, review = dict(baseline), dict(review)
            if review.get("baseline_id") != baseline["id"]:
                raise ContractError("monthly review was written against an older baseline")
            report = Path(str(review["report_path"]))
            if not report.is_absolute():
                report = Path(__file__).resolve().parents[2] / report
            try:
                report_bytes = report.read_bytes()
            except OSError as error:
                raise ContractError(f"monthly report unavailable: {position['symbol']}") from error
            if not report_bytes.strip():
                raise ContractError("monthly report is empty")
            positions.append({"position": position, "baseline": baseline, "review": review,
                              "report_sha256": hashlib.sha256(report_bytes).hexdigest()})
    payload = {"period": period, "positions": positions}
    digest = hashlib.sha256(json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    return {**payload, "context_digest": digest}

def _text(payload: dict[str, Any], key: str) -> str:
    value = payload.get(key)
    if not isinstance(value, str) or not value.strip():
        raise ContractError(f"position review requires {key}")
    return value.strip()

def _optional_text(payload: dict[str, Any], key: str) -> str | None:
    value = payload.get(key)
    if value is None:
        return None
    if not isinstance(value, str):
        raise ContractError(f"{key} must be text or null")
    return value.strip() or None

def _date(payload: dict[str, Any], key: str) -> str:
    value = _text(payload, key)
    try:
        parsed = date.fromisoformat(value)
    except ValueError as error:
        raise ContractError(f"{key} must be YYYY-MM-DD") from error
    if parsed.isoformat() != value:
        raise ContractError(f"{key} must be YYYY-MM-DD")
    return value

def _optional_positive_number(payload: dict[str, Any], key: str) -> float | None:
    value = payload.get(key)
    if value is None:
        return None
    if isinstance(value, bool) or not isinstance(value, (int, float, str)):
        raise ContractError(f"{key} must be a positive number or null")
    try:
        number = float(value)
    except (TypeError, ValueError) as error:
        raise ContractError(f"{key} must be a positive number or null") from error
    if not math.isfinite(number) or number <= 0:
        raise ContractError(f"{key} must be a positive number or null")
    return number

def _identifier(payload: dict[str, Any], key: str, *, optional: bool = False) -> int | None:
    value = payload.get(key)
    if value is None and optional:
        return None
    if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
        raise ContractError(f"{key} must be a positive integer")
    return value

def validate_position_review(payload: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(payload, dict):
        raise ContractError("position review input must be a JSON object")
    recommendation = _text(payload, "recommendation").upper()
    if recommendation not in RECOMMENDATIONS:
        raise ContractError("recommendation must be HOLD, TRIM, EXIT or NO_DECISION")
    missing_fact = _optional_text(payload, "missing_decision_fact")
    next_check_on = _optional_text(payload, "next_check_on")
    if recommendation == "NO_DECISION":
        if not missing_fact or not next_check_on:
            raise ContractError("NO_DECISION requires missing_decision_fact and next_check_on")
        next_check_on = _date({"next_check_on": next_check_on}, "next_check_on")
        if next_check_on <= _date(payload, "review_date"):
            raise ContractError("next_check_on must follow review_date")
    elif missing_fact or next_check_on:
        raise ContractError("only NO_DECISION accepts a missing fact and next check")
    return {
        "position_id": _identifier(payload, "position_id"),
        "baseline_id": _identifier(payload, "baseline_id"),
        "supersedes_review_id": _identifier(payload, "supersedes_review_id", optional=True),
        "correction_reason": _optional_text(payload, "correction_reason"),
        "review_date": _date(payload, "review_date"),
        "recommendation": recommendation,
        "summary": _text(payload, "summary"),
        "strongest_counterevidence": _text(payload, "strongest_counterevidence"),
        "report_path": _text(payload, "report_path"),
        "missing_decision_fact": missing_fact,
        "next_check_on": next_check_on,
        "reviewer": _text(payload, "reviewer"),
    }

def validate_position_event(payload: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(payload, dict):
        raise ContractError("position event input must be a JSON object")
    action = _text(payload, "action").upper()
    if action not in EVENT_ACTIONS:
        raise ContractError("position event action must be TRIM or EXIT")
    quantity = _optional_positive_number(payload, "quantity")
    if action == "TRIM" and quantity is None:
        raise ContractError("TRIM requires quantity")
    if action == "EXIT" and quantity is not None:
        raise ContractError("EXIT always closes the full remaining quantity")
    return {
        "position_id": _identifier(payload, "position_id"),
        "execution_reference": _text(payload, "execution_reference"),
        "action": action,
        "event_date": _date(payload, "event_date"),
        "quantity": quantity,
        "price": _optional_positive_number(payload, "price"),
        "reason": _text(payload, "reason"),
    }

def _required_text(payload: dict[str, Any], key: str) -> str:
    raw_value = payload.get(key)
    if not isinstance(raw_value, str):
        raise ContractError(f"position requires {key}")
    value = raw_value.strip()
    if not value:
        raise ContractError(f"position requires {key}")
    return value

def _optional_text(payload: dict[str, Any], key: str) -> str | None:
    raw_value = payload.get(key)
    if raw_value is None:
        return None
    if not isinstance(raw_value, str):
        raise ContractError(f"{key} must be text or null")
    return raw_value.strip() or None

def _strict_date_value(value: str, key: str) -> str:
    try:
        parsed = date.fromisoformat(value)
    except ValueError as error:
        raise ContractError(f"{key} must be YYYY-MM-DD") from error
    if parsed.isoformat() != value:
        raise ContractError(f"{key} must be YYYY-MM-DD")
    return value

def _optional_date(payload: dict[str, Any], key: str) -> str | None:
    value = _optional_text(payload, key)
    return _strict_date_value(value, key) if value is not None else None

def _positive_number(payload: dict[str, Any], key: str) -> float:
    value = payload.get(key)
    if value is None or isinstance(value, bool) or not isinstance(value, (int, float, str)):
        raise ContractError(f"{key} must be a positive number")
    try:
        number = float(value)
    except (TypeError, ValueError) as error:
        raise ContractError(f"{key} must be a positive number") from error
    if not math.isfinite(number) or number <= 0:
        raise ContractError(f"{key} must be a positive number")
    return number

def parse_nasdaq_quote(payload: dict[str, Any], symbol: str, role: str, retrieved_at: str) -> MarketSnapshot:
    data = payload.get("data") or {}
    if str(data.get("symbol", "")).upper() != symbol.upper():
        raise ContractError("Nasdaq response does not match requested symbol")
    primary = data.get("primaryData") or {}
    match = re.fullmatch(r"\$([0-9,]+(?:\.[0-9]+)?)", str(primary.get("lastSalePrice") or "").strip())
    if match is None:
        raise ContractError(f"Nasdaq returned no usable last-sale price for {symbol}")
    price = float(match.group(1).replace(",", ""))
    if not math.isfinite(price) or price <= 0:
        raise ContractError("Nasdaq price must be finite and positive")
    date_match = re.match(r"^[A-Z][a-z]{2} \d{1,2}, \d{4}", str(primary.get("lastTradeTimestamp") or "").strip())
    try:
        if date_match is None:
            raise ValueError("missing date prefix")
        price_date = datetime.strptime(date_match.group(0), "%b %d, %Y").date().isoformat()
    except ValueError as exc:
        raise ContractError(f"Nasdaq returned no usable trade date for {symbol}") from exc
    if date.fromisoformat(price_date) > datetime.fromisoformat(retrieved_at.replace('Z', '+00:00')).date():
        raise ContractError("Nasdaq trade date is in the future")
    return MarketSnapshot(symbol.upper(), role, price, price_date, retrieved_at, "USD", "nasdaq_info",
                          "last sale price; price return only; not total return")

class NasdaqInfoProvider:
    def __init__(self, opener: Callable[..., Any] = urllib.request.urlopen, reference_date: str | None = None) -> None:
        self._opener, self.reference_date = opener, reference_date

    def fetch(self, symbol: str, kind: str, role: str) -> MarketSnapshot:
        if kind not in {"stock", "etf"}:
            raise ContractError("Nasdaq asset kind must be stock or etf")
        query = urllib.parse.urlencode({"assetclass": "stocks" if kind == "stock" else "etf"})
        request = urllib.request.Request(NASDAQ_INFO_URL.format(symbol=urllib.parse.quote(symbol.upper()), query=query), headers=NASDAQ_HEADERS)
        retrieved_at = datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        try:
            with self._opener(request, timeout=30) as response:
                payload = json.load(response)
        except Exception as exc:
            raise ContractError(f"Nasdaq quote fetch failed for {symbol}: {exc}") from exc
        quote = parse_nasdaq_quote(payload, symbol, role, retrieved_at)
        if self.reference_date is not None:
            # Auxiliary unit-event evidence only; never substitute a Yahoo price.
            unit_quote = YahooChartProvider(symbol, "USD", reference_date=self.reference_date).fetch(symbol, kind, role)
            quote = MarketSnapshot(**{**quote.__dict__, "semantics": quote.semantics + " |units=" + unit_quote.semantics.split(" |units=", 1)[1]})
        return quote

class YahooChartProvider:
    """Explicit quote binding from the original snapshot, never a fallback."""
    def __init__(self, quote_symbol: str, currency: str, opener: Callable[..., Any] = urllib.request.urlopen, reference_date: str | None = None) -> None:
        self.quote_symbol, self.currency, self._opener = quote_symbol, currency, opener
        self.reference_date = reference_date

    def history(self, symbol: str, kind: str, role: str) -> dict[str, MarketSnapshot]:
        if kind not in {"stock", "etf"}:
            raise ContractError("Yahoo asset kind must be stock or etf")
        url = f"https://query1.finance.yahoo.com/v8/finance/chart/{urllib.parse.quote(self.quote_symbol, safe='')}?range=5d&interval=1d&events=splits"
        if self.reference_date is not None:
            since = int(datetime.combine(date.fromisoformat(self.reference_date), datetime.min.time(), timezone.utc).timestamp())
            url = url.split("?", 1)[0] + f"?period1={since}&period2={int(datetime.now(timezone.utc).timestamp())}&interval=1d&events=splits"
        now = datetime.now(timezone.utc)
        retrieved_at = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")
        try:
            with self._opener(urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"}), timeout=30) as response:
                result = json.load(response)["chart"]["result"][0]
            meta = result["meta"]
            if (meta["symbol"].upper() != self.quote_symbol.upper() or meta["currency"] != self.currency
                    or meta.get("instrumentType") != ("EQUITY" if kind == "stock" else "ETF")):
                raise ContractError("Yahoo response does not match bound listing/currency")
            zone = ZoneInfo(meta["exchangeTimezoneName"])
            regular_end = meta["currentTradingPeriod"]["regular"]["end"]
            quotes = result["indicators"]["quote"][0]["close"]
            timestamps = result["timestamp"]
            if len(quotes) != len(timestamps):
                raise ContractError("Yahoo daily bars are misaligned")
            since = max(self.reference_date or "0001-01-01", datetime.fromtimestamp(min(timestamps), zone).date().isoformat())
            breaks = sorted({datetime.fromtimestamp(int(event["date"]), zone).date().isoformat()
                             for event in result.get("events", {}).get("splits", {}).values()})
            unit_evidence = json.dumps({"since": since, "through": now.astimezone(zone).date().isoformat(),
                                        "breaks": breaks, "source": "Yahoo declared split/ratio events"}, sort_keys=True)
            rows = {}
            for stamp, price in zip(timestamps, quotes):
                day = datetime.fromtimestamp(stamp, zone).date()
                if day > now.astimezone(zone).date() or (day == now.astimezone(zone).date() and now.timestamp() < regular_end):
                    continue
                if price is None or not math.isfinite(float(price)) or float(price) <= 0:
                    continue
                rows[day.isoformat()] = MarketSnapshot(symbol.upper(), role, float(price), day.isoformat(), retrieved_at,
                    self.currency, f"yahoo_chart:{self.quote_symbol}", "unadjusted regular-session close |units=" + unit_evidence)
            if not rows:
                raise ContractError("Yahoo returned no completed daily close")
            return rows
        except ContractError:
            raise
        except Exception as error:
            raise ContractError(f"Yahoo chart fetch failed for {self.quote_symbol}: {error}") from error

    def fetch(self, symbol: str, kind: str, role: str) -> MarketSnapshot:
        rows = self.history(symbol, kind, role)
        return rows[max(rows)]

def __init__(self, quote_symbol: str, currency: str, opener: Callable[..., Any] = urllib.request.urlopen, reference_date: str | None = None) -> None:
    self.quote_symbol, self.currency, self._opener = quote_symbol, currency, opener
    self.reference_date = reference_date

def history(self, symbol: str, kind: str, role: str) -> dict[str, MarketSnapshot]:
    if kind not in {"stock", "etf"}:
