    url = f"https://query1.finance.yahoo.com/v8/finance/chart/{urllib.parse.quote(self.quote_symbol, safe='')}?range=5d&interval=1d&events=splits"
    if self.reference_date is not None:
        since = int(datetime.combine(date.fromisoformat(self.reference_date), datetime.min.time(), timezone.utc).timestamp())
        url = url.split("?", 1)[0] + f"?period1={since}&period2={int(datetime.now(timezone.utc).timestamp())}&interval=1d&events=splits"
    now = datetime.now(timezone.utc)
    retrieved_at = now.replace(microsecond=0).isoformat().replace("+00:00", "Z")
    try:
        with self._opener(urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"}), timeout=30) as response:
            result = json.load(response)["chart"]["result"][0]
        meta = result["meta"]
        if (meta["symbol"].upper() != self.quote_symbol.upper() or meta["currency"] != self.currency
                or meta.get("instrumentType") != ("EQUITY" if kind == "stock" else "ETF")):
            raise ContractError("Yahoo response does not match bound listing/currency")
        zone = ZoneInfo(meta["exchangeTimezoneName"])
        regular_end = meta["currentTradingPeriod"]["regular"]["end"]
        quotes = result["indicators"]["quote"][0]["close"]
        timestamps = result["timestamp"]
        if len(quotes) != len(timestamps):
            raise ContractError("Yahoo daily bars are misaligned")
        since = max(self.reference_date or "0001-01-01", datetime.fromtimestamp(min(timestamps), zone).date().isoformat())
        breaks = sorted({datetime.fromtimestamp(int(event["date"]), zone).date().isoformat()
                         for event in result.get("events", {}).get("splits", {}).values()})
        unit_evidence = json.dumps({"since": since, "through": now.astimezone(zone).date().isoformat(),
                                    "breaks": breaks, "source": "Yahoo declared split/ratio events"}, sort_keys=True)
        rows = {}
        for stamp, price in zip(timestamps, quotes):
            day = datetime.fromtimestamp(stamp, zone).date()
            if day > now.astimezone(zone).date() or (day == now.astimezone(zone).date() and now.timestamp() < regular_end):
                continue
            if price is None or not math.isfinite(float(price)) or float(price) <= 0:
                continue
            rows[day.isoformat()] = MarketSnapshot(symbol.upper(), role, float(price), day.isoformat(), retrieved_at,
                self.currency, f"yahoo_chart:{self.quote_symbol}", "unadjusted regular-session close |units=" + unit_evidence)
        if not rows:
            raise ContractError("Yahoo returned no completed daily close")
        return rows
    except ContractError:
        raise
    except Exception as error:
        raise ContractError(f"Yahoo chart fetch failed for {self.quote_symbol}: {error}") from error

def fetch(self, symbol: str, kind: str, role: str) -> MarketSnapshot:
    rows = self.history(symbol, kind, role)
    return rows[max(rows)]

def bound_snapshots(connection: Any, case_id: int) -> dict[str, dict[str, Any]]:
    rows = connection.execute(
        """SELECT CASE m.id WHEN s.case_snapshot_id THEN 'case'
                       WHEN s.spy_snapshot_id THEN 'spy' ELSE 'sector' END binding,m.*
           FROM shadow_entries s JOIN market_snapshots m
             ON m.id IN (s.case_snapshot_id,s.spy_snapshot_id,s.sector_snapshot_id)
           WHERE s.case_id=?""", (case_id,),
    ).fetchall()
    refs = {row["binding"]: dict(row) for row in rows}
    case = connection.execute("SELECT symbol,sector_symbol FROM cases WHERE id=?", (case_id,)).fetchone()
    if case is None or set(refs) != {'case', 'spy', 'sector'}:
        raise ContractError('market comparison requires a complete shadow binding')
    if any(refs[key]['case_id'] != case_id for key in refs):
        raise ContractError('shadow snapshot belongs to another case')
    expected = {'case': case['symbol'], 'spy': 'SPY', 'sector': case['sector_symbol']}
    if any(str(refs[key]['symbol']).upper() != str(expected[key]).upper() for key in refs):
        raise ContractError('shadow symbols do not match case binding')
    for key, ref in refs.items():
        if ref['role'] != {'case': 'case', 'spy': 'benchmark', 'sector': 'sector'}[key]:
            raise ContractError('invalid shadow snapshot role')
    compare_price_sets(refs, refs)
    return {key: canonical_snapshot(ref) for key, ref in refs.items()}

def canonical_snapshot(snapshot: Any) -> dict[str, Any]:
    ref = dict(snapshot)
    MarketSnapshot(**{field: ref[field] for field in MarketSnapshot.__dataclass_fields__})
    semantics, _, units = str(ref['semantics']).partition(' |units=')
    try:
        ref['units'] = json.loads(units) if units else ref.get('units')
        if ref['units'] is not None:
            for day in [ref['units']['since'], ref['units']['through'], *ref['units']['breaks']]:
                if date.fromisoformat(day).isoformat() != day:
                    raise ValueError('noncanonical unit evidence date')
    except (ValueError, TypeError, KeyError) as error:
        raise ContractError('invalid price-unit evidence') from error
    ref['semantics'] = semantics
    provider = str(ref['provider'])
    # Observed Yahoo labels only: retain explicit AD.AS/EUR and TM/USD-ADR listings.
    quote_symbol = provider.split(':', 1)[1] if provider.startswith('yahoo_chart:') else (
        ref['symbol'] if provider in {'yahoo_chart', 'Yahoo Finance chart API'} and ref['currency'] == 'USD' else None)
    if quote_symbol and not str(ref['semantics']).startswith(('unadjusted ', 'regular-session close')):
        quote_symbol = None
    ref['quote_symbol'] = quote_symbol
    ref['canonical_provider'] = f'yahoo_chart:{quote_symbol}' if quote_symbol else provider
    ref['canonical_semantics'] = 'unadjusted regular-session close' if quote_symbol else ref['semantics']
    return ref

def compare_price_sets(start: Any, end: Any) -> dict[str, Any]:
    """Bound local instrument price returns, without FX or dividends."""
    keys = {'case', 'spy', 'sector'}
    if set(start) != keys or set(end) != keys:
        raise ContractError('price comparison requires complete endpoint sets')
    start = {key: canonical_snapshot(row) for key, row in start.items()}
    end = {key: canonical_snapshot(row) for key, row in end.items()}
    for rows in (start, end):
        if len({row['price_date'] for row in rows.values()}) != 1:
            raise ContractError('endpoint set requires one actual trade date')
        if (rows['case']['role'] not in {'case', 'ready', 'outcome'}
                or rows['spy']['role'] != 'benchmark' or rows['sector']['role'] != 'sector'):
            raise ContractError('invalid endpoint roles')
    if end['case']['price_date'] < start['case']['price_date']:
        raise ContractError('price comparison end precedes start')
    returns = {}
    for key in keys:
        if any(start[key][field] != end[key][field] for field in
               ('symbol', 'currency', 'canonical_provider', 'canonical_semantics')):
            raise ContractError('price comparison does not match bound symbol/provider/currency/semantics')
        same_observation = (all(start[key][field] == end[key][field]
                                for field in MarketSnapshot.__dataclass_fields__ if field != 'role')
                            and start[key]['units'] == end[key]['units'])
        if not same_observation:
            units = end[key]['units']
            if not units or units['since'] > start[key]['price_date'] or units['through'] < end[key]['price_date']:
                raise ContractError('price units unresolved: no interval event coverage')
            evidence = [row['units'] for row in (start[key], end[key]) if row['units']]
            if any(start[key]['price_date'] <= day <= max(item['through'] for item in evidence)
                   for item in evidence for day in item['breaks']):
                raise ContractError('price units unresolved: split/ratio event crosses stored endpoints')
        returns[key] = (float(end[key]['price']) / float(start[key]['price']) - 1) * 100
        if not math.isfinite(returns[key]):
            raise ContractError('price return must be finite')
    return {'case_return_pct': returns['case'], 'spy_return_pct': returns['spy'],
            'sector_return_pct': returns['sector'],
            'relative_to_spy_pp': returns['case'] - returns['spy'],
            'relative_to_sector_pp': returns['case'] - returns['sector'],
            'return_basis': 'local instrument price return; no FX or dividends; not total return'}

def snapshot_set(connection: Any, case_id: int, ids: Any) -> dict[str, Any]:
    rows = {}
    for key in ('case', 'spy', 'sector'):
        row = connection.execute('SELECT * FROM market_snapshots WHERE id=? AND case_id=?',
                                 (ids[key + '_snapshot_id'], case_id)).fetchone()
        if row is None:
            raise ContractError('endpoint snapshot is missing or belongs to another case')
        rows[key] = dict(row)
    return rows

def fetch_bound_market_set(
    radar: RadarDB, symbol: str, *, case_role: str, provider: NasdaqInfoProvider | None = None,
) -> tuple[int, dict[str, MarketSnapshot]]:
    case = radar.get_case_by_symbol(symbol)
    case_id = int(str(case['id']))
    with radar.connect() as connection:
        refs = bound_snapshots(connection, case_id)
    if set(refs) != {'case', 'spy', 'sector'}:
        raise ContractError('market observation requires bound original snapshots')
    available = {}
    for key, role, kind in [('case', case_role, str(case['kind'])), ('spy', 'benchmark', 'etf'), ('sector', 'sector', 'etf')]:
        ref = refs[key]
        if provider is not None:
            quote = provider.fetch(ref['symbol'], kind, role)
            rows = {quote.price_date: quote}
        elif ref['quote_symbol']:
            source = YahooChartProvider(ref['quote_symbol'], ref['currency'], reference_date=ref['price_date'])
            rows = source.history(ref['symbol'], kind, role)
        elif ref['provider'] == 'nasdaq_info' and ref['currency'] == 'USD':
            quote = NasdaqInfoProvider(reference_date=ref['price_date']).fetch(ref['symbol'], kind, role)
            rows = {quote.price_date: quote}
        else:
            raise ContractError('unsupported bound market provider/currency')
        available[key] = rows
    common = set.intersection(*(set(rows) for rows in available.values()))
    if not common:
        raise ContractError('market snapshot set does not share one actual trade date')
    day = max(common)
    snapshots = {key: rows[day] for key, rows in available.items()}
    compare_price_sets(refs, {key: snapshot.__dict__ for key, snapshot in snapshots.items()})
    return case_id, snapshots

def observe_live(radar: RadarDB, symbol: str, provider: NasdaqInfoProvider | None = None) -> dict[str, object]:
    case_id, snapshots = fetch_bound_market_set(radar, symbol, case_role='case', provider=provider)
    ids = {}
    with radar.connect() as connection:
        connection.execute('BEGIN IMMEDIATE')
        for key, snapshot in snapshots.items():
            cursor = connection.execute(
                """INSERT INTO market_snapshots(case_id,symbol,role,price,price_date,retrieved_at,currency,provider,semantics)
                   VALUES (:case_id,:symbol,:role,:price,:price_date,:retrieved_at,:currency,:provider,:semantics)""",
                dict(snapshot.__dict__, case_id=case_id),
            )
            assert cursor.lastrowid is not None
            ids[key] = cursor.lastrowid
    return {'case_id': case_id, 'price_date': snapshots['case'].price_date, 'snapshot_ids': ids}

def record_outcome_live(
    radar: RadarDB, symbol: str, provider: NasdaqInfoProvider | None = None
) -> dict[str, object]:
    case_id, snapshots = fetch_bound_market_set(radar, symbol, case_role="outcome", provider=provider)
    outcome_id = radar.record_outcome(
        case_id, snapshots["case"], snapshots["spy"], snapshots["sector"]
    )
    row = next(item for item in evaluate_outcomes(radar) if item["outcome_id"] == outcome_id)
    return row

def event_mail(events: list[dict[str, object]]) -> str:
    lines = ["# Opportunity Radar — neues Ereignis", "", "READY bleibt eine manuelle Entscheidung im Chat.", ""]
    for event in events:
        direction = "ERREICHT" if bool(event["active"]) else "VERLOREN"
        lines.extend([f"## {event['symbol']} · {direction}", f"- Signal: `{event['signal']}`", f"- Beleg: {event['detail']}", f"- Status bleibt: **{event['status']}**", ""])
    return "\n".join(lines).rstrip() + "\n"

class MailTransport(Protocol):
    def find_verified(self, subject: str, recipient: str) -> str | None: ...
    def send_and_verify(self, subject: str, recipient: str, body: str) -> str: ...

def subject_search_token(subject: str) -> str:
    token = subject.split()[-1].strip("[]") if subject.split() else ""
    if not token or any(character.isspace() for character in token):
        raise ContractError("mail subject needs a unique final search token")
    return token

class HimalayaTransport:
    def __init__(
        self,
        *,
        sender: str | None = None,
        sent_folder: str = "INBOX.Sent",
        markdown_helper: Path | None = None,
        markdown_python: Path | None = None,
    ) -> None:
        # Export default is closed even on a host with an existing mail account.
        if os.environ.get("OPPORTUNITY_RADAR_ENABLE_MAIL") != "1":
            raise ContractError("live mail disabled; explicit configuration required")
        sender = sender or os.environ.get("OPPORTUNITY_RADAR_SENDER")
        helper = markdown_helper or os.environ.get("OPPORTUNITY_RADAR_MARKDOWN_HELPER")
        if not sender or not helper or not Path(helper).is_file():
            raise ContractError("explicit sender and existing Markdown helper required")
        markdown_helper = Path(helper)
        markdown_python = markdown_python or Path(sys.executable)
        self.sender = sender
        self.sent_folder = sent_folder
        self.markdown_helper = markdown_helper
        self.markdown_python = markdown_python

    def _verified_message(self, message_id: str, subject: str, recipient: str) -> bool:
        exported = subprocess.run(
            ["himalaya", "message", "export", "--folder", self.sent_folder, str(message_id), "--full"],
            capture_output=True,
            check=True,
        ).stdout
        return headers_match(exported, subject, recipient)

    def find_verified(self, subject: str, recipient: str) -> str | None:
        listed = subprocess.run(
            ["himalaya", "envelope", "list", "--folder", self.sent_folder, "--page-size", "30", "--output", "json", "subject", subject_search_token(subject)],
            text=True,
            capture_output=True,
        )
        if listed.returncode != 0 or listed.stderr.strip():
            raise ContractError(f"Sent search failed: {listed.stderr.strip() or listed.returncode}")
        rows = json.loads(listed.stdout or "[]")
        for row in reversed(rows):
            if str(row.get("subject", "")) != subject:
                continue
            message_id = str(row["id"])
            if self._verified_message(message_id, subject, recipient):
                return message_id
        return None

    def send_and_verify(self, subject: str, recipient: str, body: str) -> str:
        rendered = subprocess.run(
            [str(self.markdown_python), str(self.markdown_helper), "--to", recipient, "--subject", subject, "--from", self.sender],
            input=body,
            text=True,
            capture_output=True,
        )
        if rendered.returncode != 0:
            detail = rendered.stderr.strip() or rendered.stdout.strip() or f"exit {rendered.returncode}"
            raise ContractError(f"Markdown mail render failed: {detail}")
        sent = subprocess.run(
            ["himalaya", "template", "send"],
            input=rendered.stdout,
            text=True,
            capture_output=True,
        )
        if sent.returncode != 0:
            detail = sent.stderr.strip() or sent.stdout.strip() or f"exit {sent.returncode}"
            raise ContractError(f"Himalaya send failed: {detail}")
        for delay in (0.5, 1.0, 2.0, 4.0):
            message_id = self.find_verified(subject, recipient)
            if message_id is not None:
                return message_id
            time.sleep(delay)
        raise ContractError("mail sent but exact Sent verification failed")

def _verified_message(self, message_id: str, subject: str, recipient: str) -> bool:
    exported = subprocess.run(
        ["himalaya", "message", "export", "--folder", self.sent_folder, str(message_id), "--full"],
        capture_output=True,
        check=True,
    ).stdout
    return headers_match(exported, subject, recipient)

def find_verified(self, subject: str, recipient: str) -> str | None:
    listed = subprocess.run(
        ["himalaya", "envelope", "list", "--folder", self.sent_folder, "--page-size", "30", "--output", "json", "subject", subject_search_token(subject)],
        text=True,
        capture_output=True,
    )
    if listed.returncode != 0 or listed.stderr.strip():
        raise ContractError(f"Sent search failed: {listed.stderr.strip() or listed.returncode}")
    rows = json.loads(listed.stdout or "[]")
    for row in reversed(rows):
        if str(row.get("subject", "")) != subject:
            continue
        message_id = str(row["id"])
        if self._verified_message(message_id, subject, recipient):
            return message_id
    return None

def mail_attempt_path(radar: RadarDB, delivery_key: str) -> Path:
    name = hashlib.sha256(delivery_key.encode("utf-8")).hexdigest() + ".pending"
    return radar.path.parent / "mail-attempts" / name

def deliver_mail_once(
    radar: RadarDB,
    transport: MailTransport,
    delivery_key: str,
    subject: str,
    recipient: str,
    body: str,
    *,
    event_ids: list[int] | None = None,
) -> dict[str, str]:
    # Event callers hold their flock through marking and pending removal.
    # Retain their pending record even after receipt commit to close that crash gap.
    body_sha256 = hashlib.sha256(body.encode("utf-8")).hexdigest()
    identity = dict(delivery_key=delivery_key, subject=subject,
                    recipient=recipient, body_sha256=body_sha256)
    if event_ids is not None and (
        not event_ids or any(type(value) is not int or value <= 0 for value in event_ids)
        or len(set(event_ids)) != len(event_ids)
    ):
        raise ContractError("event batch needs unique positive event IDs")
    attempt_path = mail_attempt_path(radar, delivery_key)
    attempt_directory = attempt_path.parent
    pending = None
    if attempt_path.exists():
        pending = json.loads(attempt_path.read_text(encoding="utf-8"))
        if not isinstance(pending, dict) or any(pending.get(k) != v for k, v in identity.items()):
            raise ContractError("prior mail attempt has different or unbound identity/body bytes; reconcile before retry")
        if pending.get("event_ids") != event_ids or (event_ids is not None and pending.get("body") != body):
            raise ContractError("prior event batch has different or unbound event IDs/body bytes")
    receipt = radar.get_mail_receipt(delivery_key)
    if receipt is not None:
        if any(receipt.get(k) != v for k, v in identity.items()):
            raise ContractError("delivery identity already belongs to different or historically unbound identity/body bytes; reconcile explicitly")
        return {"status": "already_delivered", "message_id": str(receipt["sent_message_id"])}
    if pending is not None:
        message_id = transport.find_verified(subject, recipient)
        if message_id is None:
            raise ContractError(
                "prior mail delivery attempt is unresolved; reconcile Sent before retrying SMTP"
            )
        radar.record_mail_receipt(delivery_key, subject, recipient, message_id, body_sha256)
        if event_ids is None:
            attempt_path.unlink()
        return {"status": "recovered_from_sent", "message_id": message_id}
    message_id = transport.find_verified(subject, recipient)
    if message_id is not None:
        raise ContractError("Sent header match has no bound body receipt; reconcile explicitly instead of claiming content delivery")
    status = "recovered_from_sent"
    if message_id is None:
        attempt_directory.mkdir(parents=True, exist_ok=True)
        attempt_path.write_text(
            json.dumps(
                {**identity, **({"event_ids": event_ids, "body": body} if event_ids is not None else {})},
                ensure_ascii=False,
                sort_keys=True,
            ),
            encoding="utf-8",
        )
        message_id = transport.send_and_verify(subject, recipient, body)
        status = "sent"
    radar.record_mail_receipt(delivery_key, subject, recipient, message_id, body_sha256)
    if event_ids is None and attempt_path.exists():
        attempt_path.unlink()
    return {"status": status, "message_id": message_id}

def watch_letter_context(radar: RadarDB, period: str) -> dict[str, Any]:
    try:
        year_text, quarter_text = period.split("-Q")
        year = int(year_text)
        quarter = int(quarter_text)
    except (ValueError, TypeError) as error:
        raise ContractError("period must be YYYY-QN") from error
    if str(year) != year_text or quarter not in {1, 2, 3, 4} or period != f"{year}-Q{quarter}":
        raise ContractError("period must be YYYY-QN")
    cases = _latest_case_rows(radar)
    with radar.connect() as connection:
        active_positions = [dict(row) for row in connection.execute(
            "SELECT id,symbol,case_id,quantity FROM positions WHERE status='ACTIVE' ORDER BY id"
        )]
    held_case_ids = {item["case_id"] for item in active_positions if item["case_id"] is not None}
    awaiting_candidates = _awaiting_candidate_rows(radar)
    for item in awaiting_candidates:
        report = Path(str(item["report_path"] or ""))
        if not report.is_absolute():
            report = Path(__file__).resolve().parents[2] / report
        try:
            item["report_sha256"] = hashlib.sha256(report.read_bytes()).hexdigest()
        except OSError as error:
            raise ContractError(f"candidate report unavailable: {item['symbol']}") from error
    bound_payload = {
        "period": period,
        "watch_cases": [item for item in cases if item["status"] == "WATCH"],
        "ready_cases": [item for item in cases if item["status"] == "READY" and item["id"] not in held_case_ids],
        "active_positions": active_positions,
        "awaiting_candidates": awaiting_candidates,
    }
    context_digest = hashlib.sha256(
        json.dumps(
            bound_payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")
        ).encode("utf-8")
    ).hexdigest()
    return {**bound_payload, "context_digest": context_digest}

def _validate_outcomes(
    value: object,
    *,
    expected_symbols: list[str],
    allowed: set[str],
    field: str,
) -> None:
    if not isinstance(value, list):
        raise ContractError(f"{field} must be a list")
    symbols: list[str] = []
    for item in value:
        if not isinstance(item, dict):
            raise ContractError(f"{field} entries must be objects")
        symbol = item.get("symbol")
        outcome = item.get("outcome")
        if not isinstance(symbol, str) or not symbol:
            raise ContractError(f"{field} entries require symbol")
        if outcome not in allowed:
            raise ContractError(f"{field} contains invalid outcome")
        symbols.append(symbol)
    if len(symbols) != len(set(symbols)):
        raise ContractError(f"{field} contains duplicate symbols")
    if symbols != expected_symbols:
        raise ContractError(f"{field} must cover the current symbols in order")

def _validate_candidate_outcomes(value: object, expected: list[dict[str, Any]]) -> None:
    if not isinstance(value, list) or len(value) != len(expected):
        raise ContractError("candidate_outcomes must cover the current candidates in order")
    for item, candidate in zip(value, expected):
        if not isinstance(item, dict):
            raise ContractError("candidate_outcomes entries must be objects")
        if type(item.get("candidate_id")) is not int or any(
            item.get(key) != candidate[key]
            for key in ("candidate_id", "stable_identity", "signal_date", "symbol")
        ):
            raise ContractError("candidate_outcomes must bind exact candidate_id, stable_identity, signal_date and symbol")
        if item.get("outcome") not in CANDIDATE_OUTCOMES:
            raise ContractError("candidate_outcomes contains invalid outcome")

def validate_watch_letter_manifest(
    radar: RadarDB, period: str, manifest: dict[str, object], *, body: str | None = None
) -> dict[str, object]:
    context = watch_letter_context(radar, period)
    if manifest.get("period") != period:
        raise ContractError("watch letter manifest period mismatch")
    if manifest.get("context_digest") != context["context_digest"]:
        raise ContractError("watch letter manifest context is stale")
    if body is not None and manifest.get("body_sha256") != hashlib.sha256(body.encode("utf-8")).hexdigest():
        raise ContractError("watch letter body does not match its reviewed manifest")
    for field, group, allowed in (
        ("watch_outcomes", "watch_cases", WATCH_OUTCOMES),
        ("ready_outcomes", "ready_cases", READY_OUTCOMES),
    ):
        _validate_outcomes(
            manifest.get(field), expected_symbols=[str(item["symbol"]) for item in context[group]],
            allowed=allowed, field=field,
        )
    _validate_candidate_outcomes(manifest.get("candidate_outcomes"), context["awaiting_candidates"])
    return context

def research_history(radar: RadarDB, *, include_reports: bool = False) -> list[dict[str, Any]]:
    root = Path(__file__).resolve().parents[2]
    with radar.connect() as connection:
        items = [dict(row) for row in connection.execute("""SELECT d.*,(
            SELECT name FROM candidate_inbox ci WHERE ci.stable_identity=d.stable_identity
            ORDER BY id DESC LIMIT 1) name FROM candidate_decisions d ORDER BY d.id DESC""")]
    known = set()
    for item in items:
        if item['report_path']:
            path = Path(item['report_path'])
            known.add((path if path.is_absolute() else root / path).resolve())
    for folder in (root / 'research',root / 'output/reviews'):
        for path in sorted(folder.rglob('*.md')):
            if path.resolve() not in known:
                items.append(dict(report_path=str(path.relative_to(root)),decision=None,
                                  reader_text="Direktes Researchdokument; Urteil/Anker siehe Original"))
    for item in items:
        if not include_reports or not item.get('report_path'):
            continue
        path = Path(item['report_path'])
        path = path if path.is_absolute() else root / path
        try:
            body = path.read_text(encoding='utf-8').splitlines()
        except OSError:
            item['report_available'] = False
            continue
        item['report_available'] = True
        item['title'] = next((line.lstrip('# ').strip() for line in body if line.startswith('# ')),path.stem)
        # Quote original anchors/conclusions, never infer missing historic metadata.
        excerpts = []
        for index,line in enumerate(body):
            if any(key in line.lower() for key in ('datenstand','quellenstand','referenzkurs','urteil','fazit','entscheidung:')):
                excerpts.extend(body[index:index+3])
        item['original_anchors'] = '\n'.join(excerpts)
    return items

